    raw_response_preview: truncate(data.raw_response_preview, 500), route: 'technical_errors', needs_manual_review: true,
    repair_used: data.repair_used || true, repair_status: data.repair_status || 'failed', run_id: run_id, batch_index: batch_index
  }}];
}

const validEntities = ['competitor','lead_signal','market_signal','content_idea','irrelevant'];
const validActions = ['contact','investigate','monitor','create_content','add_to_semantics','ignore'];
const entity = data.entity_type || 'irrelevant';
const action = data.recommended_action || 'ignore';
const safeEntity = validEntities.indexOf(entity) >= 0 ? entity : 'irrelevant';
let safeAction = validActions.indexOf(action) >= 0 ? action : 'ignore';
const safeStatus = (data.status === 'skipped') ? 'skipped' : 'analyzed';
const leadScore = clamp(data.lead_signal_score);
const compScore = clamp(data.competitor_strength);
const contentScore = clamp(data.content_idea_score);
const qualScore = clamp(data.quality_score);
const contact = cleanContact(data.contact_public || src.contact_public || '');
const hasContact = contact !== '';

let route, needsReview, procStatus = 'parsed_success';
if (safeStatus === 'skipped' || safeEntity === 'irrelevant') {
  route = 'skipped_log'; needsReview = false; procStatus = 'business_skip';
} else if (safeEntity === 'lead_signal' && leadScore >= 70 && safeAction === 'contact' && hasContact) {
  route = 'results'; needsReview = false;
} else if (safeEntity === 'lead_signal') {
  route = 'review_queue'; needsReview = true;
} else if (safeEntity === 'competitor') {
  route = 'monitor_queue'; needsReview = false;
} else if (safeEntity === 'content_idea' || safeEntity === 'market_signal') {
  if (safeAction === 'ignore') { route = 'skipped_log'; needsReview = false; procStatus = 'business_skip'; }
  else { route = 'content_queue'; needsReview = true; }
} else {
  if (safeAction === 'contact') route = 'results';
  else if (safeAction === 'monitor') route = 'monitor_queue';
  else if (safeAction === 'create_content' || safeAction === 'add_to_semantics') route = 'content_queue';
  else if (safeAction === 'ignore') { route = 'skipped_log'; procStatus = 'business_skip'; }
  else route = 'review_queue';
  needsReview = (route !== 'skipped_log');
}

const validRoutes = ['results','review_queue','monitor_queue','content_queue','skipped_log','technical_errors'];
let parseError = data.parse_error || '';
if (validRoutes.indexOf(route) === -1) {
  route = 'technical_errors'; procStatus = 'technical_error'; needsReview = true;
  parseError = (parseError ? parseError + '; ' : '') + 'invalid_route';
}

let finalAction;
if (route === 'results') finalAction = 'contact';
else if (route === 'monitor_queue') finalAction = 'monitor';
else if (route === 'review_queue') finalAction = (safeEntity === 'lead_signal' && hasContact && leadScore >= 70) ? 'contact' : 'investigate';
else if (route === 'content_queue') finalAction = (safeAction === 'add_to_semantics') ? 'add_to_semantics' : 'create_content';
else if (route === 'skipped_log') finalAction = 'ignore';
else finalAction = 'ignore';

const detUsed = (data.parse_method === 'deterministic_fallback_after_llm_fail');
return [{ json: {
  created_at: data.created_at || src.parsed_at || now,
  source_type: data.source_type || src.source_type || '',
  platform: data.platform || src.platform || '',
  source_url: data.source_url || src.source_url || '',
  parsed_at: data.parsed_at || src.parsed_at || now,
  published_at: data.published_at || src.published_at || '',
  freshness_status: data.freshness_status || 'unknown',
  entity_type: safeEntity,
  company_name: data.company_name || '',
  profile_name: data.profile_name || src.profile_name || '',
  profile_url: data.profile_url || src.profile_url || '',
  region: data.region || src.region_hint || '',
  service_type: data.service_type || src.service_hint || 'unknown',
  offer_text: truncate(data.offer_text || '', 300),
  terms: truncate(data.terms || '', 220),
  contact_public: contact,
  text_context: truncate(data.text_context || src.analyzer_text || '', 3500),
  detected_need: truncate(data.detected_need || '', 300),
  competitor_strength: compScore,
  lead_signal_score: leadScore,
  content_idea_score: contentScore,
  quality_score: qualScore,
  reason: data.reason || '',
  recommended_action: finalAction,
  status: safeStatus,
  processing_status: procStatus,
  parse_method: data.parse_method || 'primary_json',
  parse_error: truncate(parseError, 800),
  raw_response_preview: truncate(data.raw_response_preview, (procStatus === 'parsed_success' && !detUsed) ? 200 : 500),
  route: route,
  needs_manual_review: detUsed ? true : needsReview,
  repair_used: data.repair_used || false,
  repair_status: data.repair_status || '',
  run_id: run_id,
  batch_index: batch_index
}}];

function str(v){return v==null?'':String(v).trim();}
let analyzed=[];let skipped=[];
try{analyzed=$('Normalize + Route').all().map(i=>i.json);}catch(e){analyzed=[];}
try{skipped=$('Build Skip Row (Irrelevant)').all().map(i=>i.json);}catch(e){skipped=[];}
const all=analyzed.concat(skipped);
const cfg=$('Set Analyzer Config').first().json;
const route_counts={};const entity_counts={};const parse_method_counts={};let repair_used=0;let tech=0;let detfb=0;
for(const r of all){
  const rt=str(r.route)||'unknown';route_counts[rt]=(route_counts[rt]||0)+1;
  const en=str(r.entity_type)||'unknown';entity_counts[en]=(entity_counts[en]||0)+1;
  const pm=str(r.parse_method)||'unknown';parse_method_counts[pm]=(parse_method_counts[pm]||0)+1;
  if(r.repair_used===true)repair_used++;
  if(rt==='technical_errors')tech++;
  if(pm==='deterministic_fallback_after_llm_fail')detfb++;
}
return [{ json: {
  workflow:'08 - Touchpoint Analyzer',
  run_id:cfg.run_id||'',
  test_mode:cfg.test_mode===true,
  total_processed:all.length,
  analyzed_rows:analyzed.length,
  deterministic_skipped_irrelevant:skipped.length,
  deterministic_fallback_after_llm_fail:detfb,
  route_counts:route_counts,
  entity_counts:entity_counts,
  parse_method_counts:parse_method_counts,
  repair_used_count:repair_used,
  technical_errors_count:tech,
  next_action:'Review the 6 business tabs and record outcomes in docs/STAGE_3_2_TEST_RESULTS.md. technical_errors should be 0 for classifiable records.'
}}];
